rules.pseudocode:
level = highest(high, breakoutLookback)[1] at bar k where close[k] > level;
failed = exists j in k-failBars..k-1 with close[j] < open[j] && close[j] < level;
barsSince(failed) >= blockBars

spikeEnded = consecutive bull trend bars >= spikeBars ending at bar k;
firstPullbackSinceSpike = bar j (low[j] < low[j+1], no earlier such bar since k);
close[0] > high[j] && (j - 0) <= maxWaitBars

// persistent: count, signalLow, minLowSince
if (close[0] > highest(high, resetLookback)[1]) { count = 0; }
else { minLowSince = min(minLowSince, low[0]);
  if (high[0] > high[1] && (count == 0 || minLowSince < signalLow)) { count = min(count + 1, 4); signalLow = low[0]; minLowSince = low[0]; justAdvanced = true; } }
count == countTarget && justAdvanced
